    // NULL screen variables
    ui_Screen1 = NULL;
    uic_inPanel = NULL;
    ui_inPanel = NULL;
    ui_HomeIcon = NULL;
    ui_inTitle = NULL;
    ui_inSeparator = NULL;
    ui_inTemp = NULL;
    ui_inHum = NULL;
    ui_inTempIcon = NULL;
    ui_InHumIcon = NULL;
    ui_InHumUinit = NULL;
    ui_InTempUnit = NULL;
    ui_outPanel = NULL;
    ui_outTitle = NULL;
    ui_TreeIcon = NULL;
    ui_outSeparator = NULL;
    ui_outTemp = NULL;
    ui_outTempIcon = NULL;
